<script setup lang="ts">
import { computed, onBeforeUnmount, ref, shallowRef, watch } from 'vue'
import { availableForecastFrames, forecastAssetUrl, loadForecastManifest, publishedForecastBases, type ForecastRun, type ForecastRegion } from '../data/forecast-models'
const props=withDefaults(defineProps<{active?:boolean}>(),{active:true})
const run=shallowRef<ForecastRun>(),region=ref<ForecastRegion>('west-pacific'),hour=ref(0),error=ref(''),loaded=ref('')
const frames=computed(()=>availableForecastFrames(run.value,region.value,'wind'))
const frame=computed(()=>frames.value.find(f=>f.hour===hour.value)),path=computed(()=>frame.value?.files[region.value]?.wind?.png),image=computed(()=>path.value?forecastAssetUrl(path.value):'')
let controller:AbortController|undefined,revision=0
async function load(){controller?.abort();if(!props.active)return;const token=++revision;controller=new AbortController();try{const m=await loadForecastManifest(controller.signal);if(token===revision){run.value=publishedForecastBases(m.runs)[0];if(!frames.value.some(f=>f.hour===hour.value))hour.value=frames.value[0]?.hour??0}}catch(e){if(token===revision&&!controller.signal.aborted)error.value=e instanceof Error?e.message:String(e)}}
watch(image,()=>loaded.value='',{flush:'sync'});watch(()=>props.active,a=>{if(a&&!run.value)void load();if(!a){++revision;controller?.abort()}},{immediate:true})
onBeforeUnmount(()=>{++revision;controller?.abort()})
</script>
<template><section class="surface-forecast card" aria-label="Published surface weather forecast"><header><h3>Surface Plot / 地表天气场</h3><p>WM-6 原生10m风／MSLP预报，不是海面实测。</p></header><div class="surface-published-controls"><label>区域<select v-model="region" aria-label="Surface forecast region"><option value="west-pacific">西北太平洋</option><option value="east-asia">东亚</option><option value="north-america">北美</option></select></label><label>有效 UTC<select v-model.number="hour" aria-label="Surface forecast lead"><option v-for="f in frames" :key="f.hour" :value="f.hour">+{{ f.hour }}h · {{ f.validTime }}</option></select></label><a href="#forecast-models">全部地表／全球预报与下载 →</a></div><p v-if="error" role="alert">{{ error }} 不用旧截图或其他产品替代。</p><template v-if="run&&frame&&image"><p>预报基准 {{ run.forecastZero }} · 有效 {{ frame.validTime }} · 已发布的128成员0.25°均场</p><a :href="image" target="_blank" rel="noopener"><img :key="image" :src="active?image:undefined" v-show="loaded===image" alt="Workflow generated WM-6 native 10m wind and MSLP forecast" @load="loaded=image" @error="error='此地表预报图暂不可读，不以其他图代替'"/></a><p v-if="loaded!==image&&!error">读取已发布地表预报图…</p></template><p v-else-if="!error">读取已发布地表图清单；缺图不补图。</p></section></template>
<style scoped>.surface-forecast{padding:16px;min-width:0}.surface-forecast h3{font-size:18px;margin:0 0 8px}.surface-forecast p{font-size:11px;line-height:1.8;color:#728ba0}.surface-published-controls{display:flex;flex-wrap:wrap;gap:12px;align-items:end}.surface-published-controls label{display:grid;gap:5px;max-width:100%;font-size:11px;min-width:0}.surface-published-controls select{padding:7px;max-width:100%;border:1px solid #cbdce6;border-radius:5px}.surface-published-controls a{font-size:11px;color:#2f83b2}.surface-forecast img{display:block;width:100%;height:auto;max-height:470px;object-fit:contain}@media(max-width:600px){.surface-published-controls label{width:100%}}</style>
